-- ANGELCARE_DCE_ADMIN_R1. Additive activation; no native table, role assignment or provider configuration is modified.
begin;
-- gen_random_uuid() is native to the supported PostgreSQL version.
do $$ declare n text; r regclass; begin
 foreach n in array array['ac_dce_records','ac_dce_versions','ac_dce_releases','ac_dce_events','ac_dce_commands','ac_dce_jobs','ac_dce_job_lines','ac_dce_links'] loop
  r:=to_regclass('public.'||n);
  if r is not null and obj_description(r,'pg_class') is distinct from 'ANGELCARE_DCE_ADMIN_R1' then raise exception 'Existing unrelated relation: %',n; end if;
 end loop;
end $$;
do $$ declare f record; begin for f in select oid,proname from pg_proc where pronamespace='public'::regnamespace and proname in('ac_dce_native_media_usage','ac_dce_write','ac_dce_release','ac_dce_release_action','ac_dce_create_import','ac_dce_import_line','ac_dce_import_links','ac_dce_overview') loop if obj_description(f.oid,'pg_proc') is distinct from 'ANGELCARE_DCE_ADMIN_R1' then raise exception 'Existing unrelated function: %',f.proname;end if;end loop;end $$;
create table if not exists public.ac_dce_records(
 id uuid primary key default gen_random_uuid(),kind text not null check(kind in('experience','topic','content','asset','template','bundle','access_policy','offer_link','contribution','case','setting','ad_connection','ad_unit','ad_policy','run','grant')),
 key text not null check(key ~ '^[a-z0-9][a-z0-9._-]{1,119}$'),title text not null, family text,topic text,audience text not null check(audience in('child','parent','educator','professional','school')),
 data jsonb not null default '{}',lifecycle text not null default 'draft',revision integer not null default 1 check(revision>0),published_release_id uuid,
 created_by text not null,updated_by text not null,tenant_id text,territory_id text,
 scope_key text generated always as(coalesce(tenant_id,'~')||'|'||coalesce(territory_id,'~')) stored,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(kind,key,scope_key),check(octet_length(data::text)<=600000)
);
create table if not exists public.ac_dce_versions(id uuid primary key default gen_random_uuid(),record_id uuid references public.ac_dce_records on delete cascade,revision int not null,snapshot jsonb not null,actor_id text not null,created_at timestamptz not null default now(),unique(record_id,revision));
create table if not exists public.ac_dce_releases(id uuid primary key default gen_random_uuid(),record_id uuid not null references public.ac_dce_records,revision int not null,snapshot jsonb not null,manifest jsonb not null,validation jsonb not null,state text not null check(state in('scheduled','published','withdrawn','cancelled','failed')),scheduled_at timestamptz,published_at timestamptz,actor_id text not null,tenant_id text,territory_id text,created_at timestamptz not null default now(),error text);
create table if not exists public.ac_dce_events(id bigint generated by default as identity primary key,channel text not null check(channel in('admin','experience','provider')),action text not null,record_id uuid,actor_id text,request_id uuid,data jsonb not null default '{}',tenant_id text,territory_id text,created_at timestamptz not null default now());
create table if not exists public.ac_dce_commands(request_id uuid not null,actor_id text not null,input_hash text not null,response jsonb not null,created_at timestamptz not null default now(),primary key(request_id,actor_id));
create table if not exists public.ac_dce_links(record_id uuid references public.ac_dce_records on delete cascade,target_type text not null check(target_type in('record','media','offer')),target_id uuid not null,primary key(record_id,target_type,target_id));
create table if not exists public.ac_dce_jobs(id uuid primary key default gen_random_uuid(),task text not null,family text,source_name text not null,source_hash text not null,state text not null default 'prepared',actor_id text not null,tenant_id text,territory_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ac_dce_job_lines(id uuid primary key default gen_random_uuid(),job_id uuid references public.ac_dce_jobs on delete cascade,row_number int not null,prepared jsonb not null,issues jsonb not null default '[]',state text not null default 'ready' check(state in('ready','invalid','applied','failed','conflict','rolled_back')),before_snapshot jsonb,after_snapshot jsonb,error text,updated_at timestamptz not null default now(),unique(job_id,row_number));
create index if not exists ac_dce_records_scope on public.ac_dce_records(scope_key,kind,lifecycle,updated_at desc,id);
create index if not exists ac_dce_events_scope on public.ac_dce_events(tenant_id,territory_id,created_at desc);
create index if not exists ac_dce_links_target on public.ac_dce_links(target_type,target_id);
create index if not exists ac_dce_releases_due on public.ac_dce_releases(state,scheduled_at);
do $$ declare n text; begin foreach n in array array['ac_dce_records','ac_dce_versions','ac_dce_releases','ac_dce_events','ac_dce_commands','ac_dce_jobs','ac_dce_job_lines','ac_dce_links'] loop
 execute format('comment on table public.%I is %L',n,'ANGELCARE_DCE_ADMIN_R1');execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public',n);
 if exists(select 1 from pg_roles where rolname='anon') then execute format('revoke all on public.%I from anon',n);end if;
 if exists(select 1 from pg_roles where rolname='authenticated') then execute format('revoke all on public.%I from authenticated',n);end if;
 if exists(select 1 from pg_roles where rolname='service_role') then execute format('grant all on public.%I to service_role',n);end if;
end loop;end $$;

-- The existing native Media Library sees DCE dependencies through its own usage authority.
create or replace function public.ac_dce_native_media_usage() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if to_regclass('public.angelcare_marketplace_media_usage') is null then return coalesce(new,old);end if;
 if tg_op='DELETE' and old.target_type='media' then execute 'delete from public.angelcare_marketplace_media_usage where object_type=$1 and object_id=$2 and media_asset_id=$3' using 'digital_customer_experience',old.record_id,old.target_id;
 elsif tg_op='INSERT' and new.target_type='media' then execute 'insert into public.angelcare_marketplace_media_usage(media_asset_id,object_type,object_id,slot_key,locale) values($1,$2,$3,$4,$5)' using new.target_id,'digital_customer_experience',new.record_id,'dce-binding-'||new.target_id::text,'all';end if;
 return coalesce(new,old);
end $$;
drop trigger if exists ac_dce_native_media_usage_trigger on public.ac_dce_links;
create trigger ac_dce_native_media_usage_trigger after insert or delete on public.ac_dce_links for each row execute function public.ac_dce_native_media_usage();

create or replace function public.ac_dce_write(p_actor text,p_tenant text,p_territory text,p_request uuid,p_hash text,p_action text,p_id uuid,p_revision int,p_record jsonb,p_refs jsonb default '{}') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare r ac_dce_records; old ac_dce_records; reply jsonb; receipt ac_dce_commands; s text:=coalesce(p_tenant,'~')||'|'||coalesce(p_territory,'~'); k text; v jsonb;
begin
 if nullif(p_actor,'') is null then raise exception 'ACTOR_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor||p_request::text,0));
 select * into receipt from ac_dce_commands where actor_id=p_actor and request_id=p_request;
 if found then if receipt.input_hash<>p_hash then raise exception 'IDEMPOTENCY_CONFLICT';end if;return receipt.response;end if;
 if p_id is not null then select * into old from ac_dce_records where id=p_id and scope_key=s for update;if not found then raise exception 'NOT_FOUND';end if;if old.revision<>p_revision then raise exception 'REVISION_CONFLICT';end if;end if;
 if p_action='save' then
  if p_id is null then insert into ac_dce_records(kind,key,title,family,topic,audience,data,lifecycle,created_by,updated_by,tenant_id,territory_id) values(p_record->>'kind',p_record->>'key',p_record->>'title',p_record->>'family',p_record->>'topic',p_record->>'audience',p_record->'data',case when p_record->>'kind'='case' then 'open' when p_record->>'kind'='contribution' then 'pending' else 'draft' end,p_actor,p_actor,p_tenant,p_territory) returning * into r;
  else
   if old.kind<>p_record->>'kind' or old.key<>p_record->>'key' then raise exception 'IDENTITY_IMMUTABLE';end if;
   update ac_dce_records set title=p_record->>'title',family=p_record->>'family',topic=p_record->>'topic',audience=p_record->>'audience',data=p_record->'data',lifecycle=case when old.lifecycle in('review','approved') then 'draft' else old.lifecycle end,revision=revision+1,updated_by=p_actor,updated_at=now() where id=p_id returning * into r;
  end if;
  delete from ac_dce_links where record_id=r.id;
  for k,v in select * from jsonb_each(p_refs) loop if k not in('record','media','offer') then raise exception 'REFERENCE_TYPE';end if;insert into ac_dce_links select r.id,k,x::uuid from jsonb_array_elements_text(v) x on conflict do nothing;end loop;
 insert into ac_dce_links select r.id,'media',key::uuid from ac_dce_releases z cross join lateral jsonb_object_keys(coalesce(z.manifest->'bindings'->'media','{}')) as key where z.record_id=r.id and z.state in('published','scheduled','withdrawn') on conflict do nothing;
 elsif p_action in('review','approve','archive','open','assigned','waiting_customer','resolved','closed','hidden','rejected','accept') then
  if p_id is null then raise exception 'NOT_FOUND';end if;
  if p_action='approve' and old.lifecycle<>'review' then raise exception 'REVIEW_REQUIRED';end if;
  if p_action in('open','assigned','waiting_customer','resolved','closed') and old.kind<>'case' then raise exception 'CASE_REQUIRED';end if;
  if p_action in('hidden','rejected','accept') and old.kind<>'contribution' then raise exception 'CONTRIBUTION_REQUIRED';end if;
  if p_action='archive' and (old.published_release_id is not null or exists(select 1 from ac_dce_links where target_type='record' and target_id=old.id)) then raise exception 'DEPENDENCY_BLOCKED';end if;
  update ac_dce_records set data=case when nullif(p_record->>'reason','') is not null then data||jsonb_build_object('decisions',coalesce(data->'decisions','[]')||jsonb_build_array(jsonb_build_object('action',p_action,'reason',p_record->>'reason','actorId',p_actor,'createdAt',now()))) else data end,lifecycle=case when p_action='approve' then 'approved' when p_action='archive' then 'archived' when p_action='accept' then 'approved' else p_action end,revision=revision+1,updated_at=now(),updated_by=p_actor where id=p_id returning * into r;
 elsif p_action='delete' then
  if p_id is null or old.lifecycle not in('archived','closed','rejected') or exists(select 1 from ac_dce_releases where record_id=p_id) or exists(select 1 from ac_dce_links where target_type='record' and target_id=p_id) then raise exception 'DELETE_BLOCKED';end if;
  delete from ac_dce_records where id=p_id;r:=old;
 else raise exception 'UNKNOWN_ACTION';end if;
 if p_action<>'delete' then insert into ac_dce_versions(record_id,revision,snapshot,actor_id) values(r.id,r.revision,to_jsonb(r),p_actor);end if;
 insert into ac_dce_events(channel,action,record_id,actor_id,request_id,data,tenant_id,territory_id) values('admin',p_action,r.id,p_actor,p_request,jsonb_build_object('revision',r.revision,'kind',r.kind),p_tenant,p_territory);
 reply:=jsonb_build_object('record',to_jsonb(r),'action',p_action,'receipt',p_request);insert into ac_dce_commands values(p_request,p_actor,p_hash,reply,now());return reply;
end $$;

create or replace function public.ac_dce_release(p_actor text,p_tenant text,p_territory text,p_request uuid,p_hash text,p_id uuid,p_revision int,p_manifest jsonb,p_validation jsonb,p_schedule timestamptz default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare r ac_dce_records; z ac_dce_releases; c ac_dce_commands; reply jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_actor||p_request::text,0));select * into c from ac_dce_commands where actor_id=p_actor and request_id=p_request;if found then if c.input_hash<>p_hash then raise exception 'IDEMPOTENCY_CONFLICT';end if;return c.response;end if;
 select * into r from ac_dce_records where id=p_id and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;
 if not found then raise exception 'NOT_FOUND';end if;if r.revision<>p_revision then raise exception 'REVISION_CONFLICT';end if;
 if r.lifecycle<>'approved' or coalesce((p_validation->>'valid')::boolean,false) is not true then raise exception 'APPROVAL_REQUIRED';end if;
 if r.kind not in('experience','template','bundle','content','ad_policy','access_policy') then raise exception 'UNSUPPORTED_RELEASE';end if;
 if p_schedule is not null and p_schedule<=now() then raise exception 'FUTURE_DATE_REQUIRED';end if;
 insert into ac_dce_releases(record_id,revision,snapshot,manifest,validation,state,scheduled_at,published_at,actor_id,tenant_id,territory_id) values(r.id,r.revision,to_jsonb(r),p_manifest,p_validation,case when p_schedule is null then 'published' else 'scheduled' end,p_schedule,case when p_schedule is null then now() end,p_actor,p_tenant,p_territory) returning * into z;
 if p_schedule is null then update ac_dce_records set published_release_id=z.id where id=r.id;end if;
 insert into ac_dce_events(channel,action,record_id,actor_id,request_id,data,tenant_id,territory_id) values('admin',case when p_schedule is null then 'release' else 'schedule' end,r.id,p_actor,p_request,jsonb_build_object('releaseId',z.id,'revision',r.revision,'publicRuntimeReady',false),p_tenant,p_territory);
 reply:=jsonb_build_object('release',to_jsonb(z),'receipt',p_request);insert into ac_dce_commands values(p_request,p_actor,p_hash,reply,now());return reply;
end $$;

create or replace function public.ac_dce_release_action(p_actor text,p_tenant text,p_territory text,p_request uuid,p_hash text,p_id uuid,p_action text,p_manifest jsonb default null,p_error text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare z ac_dce_releases; r ac_dce_records; c ac_dce_commands; reply jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_actor||p_request::text,0));select * into c from ac_dce_commands where actor_id=p_actor and request_id=p_request;if found then if c.input_hash<>p_hash then raise exception 'IDEMPOTENCY_CONFLICT';end if;return c.response;end if;
 select * into z from ac_dce_releases where id=p_id and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;if not found then raise exception 'NOT_FOUND';end if;
 select * into r from ac_dce_records where id=z.record_id for update;
 if p_action='due' then
  if z.state<>'scheduled' or z.scheduled_at>now() then raise exception 'NOT_DUE';end if;if r.revision<>z.revision or r.lifecycle<>'approved' or p_manifest is null then raise exception 'REVISION_CONFLICT';end if;
  update ac_dce_releases set state='published',published_at=now(),manifest=p_manifest where id=z.id returning * into z;update ac_dce_records set published_release_id=z.id where id=r.id;
 elsif p_action='cancel' then if z.state<>'scheduled' then raise exception 'NOT_SCHEDULED';end if;update ac_dce_releases set state='cancelled' where id=z.id returning * into z;
 elsif p_action='fail' then if z.state<>'scheduled' then raise exception 'NOT_SCHEDULED';end if;update ac_dce_releases set state='failed',error=left(p_error,500) where id=z.id returning * into z;
 elsif p_action in('withdraw','restore') then
  if p_action='withdraw' and (z.state<>'published' or r.published_release_id<>z.id) then raise exception 'NOT_CURRENT_RELEASE';end if;
  if p_action='restore' and (z.state not in('withdrawn','published') or p_manifest is null) then raise exception 'RESTORE_BLOCKED';end if;
  update ac_dce_releases set state=case when p_action='withdraw' then 'withdrawn' else 'published' end,manifest=coalesce(p_manifest,manifest),published_at=case when p_action='restore' then now() else published_at end where id=z.id returning * into z;
  update ac_dce_records set published_release_id=case when p_action='restore' then z.id else null end,revision=revision+1,updated_by=p_actor,updated_at=now() where id=r.id returning * into r;insert into ac_dce_versions(record_id,revision,snapshot,actor_id) values(r.id,r.revision,to_jsonb(r),p_actor);
 else raise exception 'UNKNOWN_ACTION';end if;
 insert into ac_dce_events(channel,action,record_id,actor_id,request_id,data,tenant_id,territory_id) values('admin',p_action,r.id,p_actor,p_request,jsonb_build_object('releaseId',z.id,'revision',z.revision),p_tenant,p_territory);
 reply:=jsonb_build_object('release',to_jsonb(z),'receipt',p_request);insert into ac_dce_commands values(p_request,p_actor,p_hash,reply,now());return reply;
end $$;

create or replace function public.ac_dce_create_import(p_actor text,p_tenant text,p_territory text,p_task text,p_family text,p_name text,p_hash text,p_lines jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare j ac_dce_jobs; n int:=0; x jsonb;
begin
 if jsonb_array_length(p_lines)>5000 then raise exception 'BATCH_LIMIT';end if;
 insert into ac_dce_jobs(task,family,source_name,source_hash,actor_id,tenant_id,territory_id) values(p_task,p_family,p_name,p_hash,p_actor,p_tenant,p_territory) returning * into j;
 for x in select * from jsonb_array_elements(p_lines) loop n:=n+1;insert into ac_dce_job_lines(job_id,row_number,prepared,issues,state) values(j.id,n,x->'prepared',coalesce(x->'issues','[]'),case when jsonb_array_length(coalesce(x->'issues','[]'))>0 then 'invalid' else 'ready' end);end loop;
 insert into ac_dce_events(channel,action,actor_id,data,tenant_id,territory_id) values('admin','import_prepare',p_actor,jsonb_build_object('jobId',j.id,'rows',n,'task',p_task),p_tenant,p_territory);return to_jsonb(j);
end $$;
create or replace function public.ac_dce_import_line(p_actor text,p_tenant text,p_territory text,p_id uuid,p_action text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare l ac_dce_job_lines; j ac_dce_jobs; r ac_dce_records; reply jsonb; p jsonb;
begin
 select * into l from ac_dce_job_lines where id=p_id for update;if not found then raise exception 'NOT_FOUND';end if;
 select * into j from ac_dce_jobs where id=l.job_id and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;if not found then raise exception 'NOT_FOUND';end if;
 if p_action='apply' then
  if l.state='applied' then return to_jsonb(l);end if;if l.state<>'ready' then raise exception 'LINE_NOT_READY';end if;p:=l.prepared;
  if nullif(p->>'id','') is not null then select * into r from ac_dce_records where id=(p->>'id')::uuid and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;if not found then raise exception 'NOT_FOUND';end if;if r.revision<>(p->>'revision')::int then raise exception 'REVISION_CONFLICT';end if;end if;
  reply:=ac_dce_write(p_actor,p_tenant,p_territory,l.id,md5(p::text),'save',nullif(p->>'id','')::uuid,coalesce((p->>'revision')::int,0),p->'record',coalesce(p->'refs','{}'));
  update ac_dce_job_lines set state='applied',before_snapshot=case when r.id is not null then to_jsonb(r) end,after_snapshot=reply->'record',error=null,updated_at=now() where id=l.id returning * into l;
 elsif p_action='rollback' then
  if l.state='rolled_back' then return to_jsonb(l);end if;if l.state<>'applied' then raise exception 'LINE_NOT_APPLIED';end if;
  select * into r from ac_dce_records where id=(l.after_snapshot->>'id')::uuid for update;
  if not found or r.revision<>(l.after_snapshot->>'revision')::int or r.data is distinct from l.after_snapshot->'data' or r.published_release_id is not null then raise exception 'LATER_EDIT_BLOCKED';end if;
  if l.before_snapshot is null then if exists(select 1 from ac_dce_links where target_type='record' and target_id=r.id) then raise exception 'DEPENDENCY_BLOCKED';end if;delete from ac_dce_records where id=r.id;
  else p:=l.before_snapshot;update ac_dce_records set data=p->'data',title=p->>'title',family=p->>'family',topic=p->>'topic',audience=p->>'audience',lifecycle=p->>'lifecycle',revision=revision+1,updated_by=p_actor,updated_at=now() where id=r.id returning * into r;insert into ac_dce_versions(record_id,revision,snapshot,actor_id) values(r.id,r.revision,to_jsonb(r),p_actor);delete from ac_dce_links where record_id=r.id;end if;
  update ac_dce_job_lines set state='rolled_back',updated_at=now() where id=l.id returning * into l;
 else raise exception 'UNKNOWN_ACTION';end if;
 update ac_dce_jobs set state=case when exists(select 1 from ac_dce_job_lines where job_id=j.id and state in('ready','invalid','failed','conflict')) then 'partial' when p_action='rollback' then 'rolled_back' else 'applied' end,updated_at=now() where id=j.id;
 insert into ac_dce_events(channel,action,actor_id,data,tenant_id,territory_id) values('admin','import_'||p_action,p_actor,jsonb_build_object('jobId',j.id,'lineId',l.id),p_tenant,p_territory);return to_jsonb(l);
end $$;
-- Restore dependency links from the before image after rollback, within the same transaction.
-- The service supplies a prepared reference list under refsBefore, not arbitrary SQL.
create or replace function public.ac_dce_import_links() returns trigger language plpgsql set search_path=public,pg_temp as $$ declare k text;v jsonb; begin
 if new.state='rolled_back' and new.before_snapshot is not null then for k,v in select * from jsonb_each(coalesce(new.prepared->'refsBefore','{}')) loop insert into ac_dce_links select (new.before_snapshot->>'id')::uuid,k,x::uuid from jsonb_array_elements_text(v) x on conflict do nothing;end loop;end if;return new;end $$;
drop trigger if exists ac_dce_import_links_trigger on public.ac_dce_job_lines;
create trigger ac_dce_import_links_trigger after update on public.ac_dce_job_lines for each row execute function public.ac_dce_import_links();

create or replace function public.ac_dce_overview(p_tenant text,p_territory text,p_since timestamptz) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 with r as(select * from ac_dce_records where tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory),t as(select * from ac_dce_events where channel='experience' and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory and created_at>=p_since)
 select jsonb_build_object('experiences',(select count(*) from r where kind='experience'),'published',(select count(*) from r where kind='experience' and published_release_id is not null),'drafts',(select count(*) from r where kind='experience' and lifecycle='draft'),'assets',(select count(*) from r where kind='asset'),'visitors',case when exists(select 1 from t) then(select count(distinct data->>'visitorId') from t) else null end,'engagement',case when exists(select 1 from t) then (select count(*) filter(where action in('checkpoint','complete'))::numeric/count(*) from t) else null end,'byFamily',coalesce((select jsonb_object_agg(family,n) from(select family,count(*) n from r where kind='experience' and family is not null group by family)x),'{}'),'byTopic',coalesce((select jsonb_object_agg(topic,n) from(select topic,count(*) n from r where kind='experience' and topic is not null group by topic)x),'{}'),'byKind',coalesce((select jsonb_object_agg(kind,n) from(select kind,count(*) n from r group by kind)x),'{}'),'checkedAt',now(),'scope',coalesce(p_tenant,'~')||'|'||coalesce(p_territory,'~'));
$$;

do $$ declare f regprocedure; begin for f in select oid::regprocedure from pg_proc where pronamespace='public'::regnamespace and proname in('ac_dce_native_media_usage','ac_dce_write','ac_dce_release','ac_dce_release_action','ac_dce_create_import','ac_dce_import_line','ac_dce_import_links','ac_dce_overview') loop execute format('comment on function %s is %L',f,'ANGELCARE_DCE_ADMIN_R1');execute format('revoke all on function %s from public',f);if exists(select 1 from pg_roles where rolname='anon') then execute format('revoke all on function %s from anon',f);end if;if exists(select 1 from pg_roles where rolname='authenticated') then execute format('revoke all on function %s from authenticated',f);end if;if exists(select 1 from pg_roles where rolname='service_role') then execute format('grant execute on function %s to service_role',f);end if;end loop;
if exists(select 1 from pg_roles where rolname='service_role') then grant usage,select on sequence public.ac_dce_events_id_seq to service_role;end if;end $$;
-- Register powers in the existing native catalogue, without assigning or changing any role.
do $$ begin if to_regclass('public.angelcare_marketplace_permissions') is not null then
 insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive)
 values ('marketplace.digital_experience.view','Digital experiences · View','digital_experience',false),('marketplace.digital_experience.manage','Digital experiences · Author','digital_experience',false),('marketplace.digital_experience.publish','Digital experiences · Publish','digital_experience',true),('marketplace.digital_experience.moderate','Digital experiences · Moderate','digital_experience',true),('marketplace.digital_experience.monetize','Digital experiences · Monetize','digital_experience',true),('marketplace.digital_experience.export','Digital experiences · Export','digital_experience',true),('marketplace.digital_experience.purge','Digital experiences · Purge','digital_experience',true) on conflict(permission_key) do nothing;
end if;end $$;
notify pgrst,'reload schema';commit;
